"""Course graph: courses and prerequisite edges, with cycle detection."""

from __future__ import annotations


class CycleError(ValueError):
    """Raised when the prerequisite graph contains a cycle.

    Attributes:
        cycle: One full cycle path, e.g. ``['algebra2', 'geometry', 'algebra2']``
            (starts and ends with the same course).
    """

    def __init__(self, cycle: list[str]):
        self.cycle = list(cycle)
        super().__init__(" -> ".join(self.cycle))


class CourseGraph:
    """A directed acyclic graph of courses; edge prereq -> course means
    ``prereq`` must be completed before ``course``."""

    def __init__(self) -> None:
        self._prereqs: dict[str, set[str]] = {}  # course -> its direct prereqs
        self._dependents: dict[str, set[str]] = {}  # course -> courses that need it

    def add_course(self, course_id: str) -> None:
        """Register a course (idempotent)."""
        if not isinstance(course_id, str) or not course_id:
            raise ValueError("course id must be a non-empty string")
        self._prereqs.setdefault(course_id, set())
        self._dependents.setdefault(course_id, set())

    def add_prereq(self, course: str, prereq: str) -> None:
        """Declare that ``prereq`` must be completed before ``course``."""
        self.add_course(course)
        self.add_course(prereq)
        if course == prereq:
            raise CycleError([course, prereq])
        self._prereqs[course].add(prereq)
        self._dependents[prereq].add(course)

    @property
    def courses(self) -> set[str]:
        return set(self._prereqs)

    def prereqs_of(self, course: str) -> set[str]:
        return set(self._prereqs.get(course, ()))

    def has_cycle_dfs(
        self,
        node: str,
        visited: set[str],
        in_stack: set[str],
        path_stack: list[str],
    ) -> list[str] | None:
        """Recursive DFS helper. Returns a cycle path if found, else None."""
        visited.add(node)
        in_stack.add(node)
        path_stack.append(node)

        for nxt in sorted(self._dependents.get(node, ())):
            if nxt not in visited:
                found = self.has_cycle_dfs(nxt, visited, in_stack, path_stack)
                if found is not None:
                    return found
            elif nxt in in_stack:
                # Found a back-edge; slice out the cycle and close the loop.
                idx = path_stack.index(nxt)
                return path_stack[idx:] + [nxt]

        path_stack.pop()
        in_stack.discard(node)
        return None

    def validate(self) -> None:
        """Raise :class:`CycleError` (with one full cycle path) if a cycle exists."""
        visited: set[str] = set()
        for node in sorted(self._prereqs):
            if node not in visited:
                cycle = self.has_cycle_dfs(node, visited, set(), [])
                if cycle is not None:
                    raise CycleError(cycle)

    def toposort_all(self) -> list[str]:
        """Deterministic topological order of all courses (alphabetical tie-break).

        Raises CycleError if the graph is cyclic.
        """
        import heapq

        indegree = {c: len(self._prereqs[c]) for c in self._prereqs}
        ready = [c for c, d in indegree.items() if d == 0]
        heapq.heapify(ready)
        order: list[str] = []
        while ready:
            node = heapq.heappop(ready)
            order.append(node)
            for dep in self._dependents.get(node, ()):
                indegree[dep] -= 1
                if indegree[dep] == 0:
                    heapq.heappush(ready, dep)
        if len(order) != len(indegree):
            leftover = next(sorted(set(indegree) - set(order)))
            # Fall back to DFS to produce an exact cycle path for the error.
            self.validate()  # guaranteed to raise
            raise CycleError([leftover, leftover])
        return order

