"""Mastery progress tracking on top of a prerequisite DAG."""

from __future__ import annotations

import heapq

from .graph import CourseGraph, CycleError


class ProgressTracker:
    """Tracks which courses are unlocked and computes mastery paths."""

    def __init__(self, graph: CourseGraph):
        self.graph = graph
        graph.validate()  # fail fast on cyclic graphs

    def unlocked(self, completed: set[str]) -> set[str]:
        """Courses whose prerequisites are ALL in ``completed`` and that are
        not themselves completed."""
        completed = set(completed)
        result: set[str] = set()
        for course, prereqs in self.graph._prereqs.items():
            if course in completed:
                continue
            if prereqs <= completed:
                result.add(course)
        return result

    def _transitive_prereqs(self, target: str) -> set[str]:
        seen: set[str] = set()
        stack = [target]
        while stack:
            node = stack.pop()
            for p in self.graph._prereqs.get(node, ()):
                if p not in seen:
                    seen.add(p)
                    stack.append(p)
        return seen

    def mastery_path(self, target: str) -> list[str]:
        """A valid study order of all transitive prerequisites of ``target``
        plus ``target`` itself. Ties broken alphabetically.

        Raises KeyError if the target is unknown; CycleError if cyclic.
        """
        if target not in self.graph._prereqs:
            raise KeyError(f"unknown course: {target!r}")

        needed = self._transitive_prereqs(target)
        needed.add(target)

        # Kahn's algorithm restricted to the needed subgraph,
        # always popping the alphabetically smallest available course.
        indegree: dict[str, int] = {}
        dependents: dict[str, list[str]] = {c: [] for c in needed}
        for course in needed:
            prereqs = self.graph._prereqs[course] & needed - {course} & needed
            prereqs = self.graph._prereqs[course] & needed
            indegree[course] = len(prereqs)
            for p in prereqs:
                dependents[p].append(course)

        ready = [c for c, d in indegree.items() if d == 0]
        heapq.heapify(ready)
        order: list[str] = []
        while ready:
            node = heapq.heappop(ready)
            order.append(node)
            for dep in sorted(dependents[node]):
                indegree[dep] -= 1
                if indegree[dep] == 0:
                    heapq.heappush(ready, dep)

        if len(order) != len(needed):
            raise CycleError([target, target])  # unreachable: ctor validated
        return order

