"""Tests for the diamond dependency scenario."""

import pytest

from mastery import CourseGraph, ProgressTracker


@pytest.fixture
def diamond():
    """a -> b, a -> c, b -> d, c -> d  (arrow = is-prerequisite-of)."""
    g = CourseGraph()
    for cid in ("a", "b", "c", "d"):
        g.add_course(cid)
    g.add_prereq("b", "a")
    g.add_prereq("c", "a")
    g.add_prereq("d", "b")
    g.add_prereq("d", "c")
    g.validate()
    return ProgressTracker(g)


def test_diamond_root_unlocks_first(diamond):
    assert diamond.unlocked(set()) == {"a"}


def test_diamond_d_locked_after_one_branch(diamond):
    # a done: b and c unlock, but d still needs BOTH b and c.
    assert diamond.unlocked({"a"}) == {"b", "c"}
    assert "d" not in diamond.unlocked({"a", "b"})


def test_diamond_d_unlocks_only_after_both_b_and_c(diamond):
    assert diamond.unlocked({"a", "b", "c"}) == {"d"}
    assert diamond.unlocked({"a", "b", "c", "d"}) == set()


def test_diamond_mastery_path_is_valid_topological_order(diamond):
    path = diamond.mastery_path("d")
    assert sorted(path) == ["a", "b", "c", "d"]
    pos = {course: i for i, course in enumerate(path)}
    for prereq, course in (("a", "b"), ("a", "c"), ("b", "d"), ("c", "d")):
        assert pos[prereq] < pos[course]

